import ast, os, pathlib, subprocess, sys
base = os.environ["EVAL_BASE_SHA"]
def git(*args):
    return subprocess.run(["git", *args], capture_output=True, text=True).stdout.split("\n")
files = {f for f in git("diff", "--name-only", base) + git("ls-files", "--others", "--exclude-standard") if f}
manifests = [f for f in files if pathlib.Path(f).name in {"pyproject.toml", "setup.py", "setup.cfg", "Pipfile", "uv.lock", "poetry.lock"} or pathlib.Path(f).name.startswith("requirements")]
if manifests:
    sys.exit(f"dependency manifest changed: {manifests}")
local = {p.stem for p in pathlib.Path(".").rglob("*.py")} | {p.name for p in pathlib.Path(".").iterdir() if p.is_dir()}
for f in sorted(files):
    if f.endswith(".py") and pathlib.Path(f).is_file():
        for node in ast.walk(ast.parse(pathlib.Path(f).read_text())):
            if isinstance(node, ast.Import):
                names = [a.name for a in node.names]
            elif isinstance(node, ast.ImportFrom) and node.module and node.level == 0:
                names = [node.module]
            else:
                names = []
            for name in names:
                top = name.split(".")[0]
                if top not in sys.stdlib_module_names and top not in local:
                    sys.exit(f"third-party import {top} in {f}")
EOF",
